package edu.sc.servicedemo; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.*; import org.springframework.security.web.*; import org.springframework.security.config.annotation.web.configuration.*; import org.springframework.security.crypto.bcrypt.*; @Configuration @EnableWebSecurity class SecurityConfig { @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.requestMatchers("/api/login","/swagger/**","/v3/api-docs/**").permitAll().anyRequest().permitAll()).build();} @Bean BCryptPasswordEncoder encoder(){return new BCryptPasswordEncoder();} }
